/** Projeto independente. Não reutiliza IDs nem dados do Salém. */
const PDA = Object.freeze({
  parent:'10alyWnpE3WW3Q-Q0PeZ2RsSZvpAkEubR',
  name:'Povo das Águas',
  tz:'America/Sao_Paulo',
  maxBytes:5*1024*1024
});

const SEGURO_DEFESO_2025 = Object.freeze({
  salarioMinimo:1518.00,
  minParcelas:1,
  maxParcelas:4,
  modeloNome:'INICIAL - SEGURO DEFESO 2025'
});

const SCHEMA = Object.freeze({
  Pessoas:[
    'nome','cpf','nascimento','telefone','tipoVia','via','numero','complemento',
    'bairro','cidade','uf','entidade','outraEntidade','analfabeto',
    'parcelasNaoRecebidas','jurisdicao'
  ],
  Atendimentos:[
    'pessoaId','demanda','referencia','parcelas','outrosCasos','observacoes',
    'responsavel','situacao','folderId','revisao','conferencia','enderecamento',
    'secaoJudiciaria','valorCausa','localData'
  ],
  Documentos:[
    'atendimentoId','categoria','fileId','url','nome','hash','mime','substituiId',
    'vigente','vencimento','terceiro','conferido','declaracaoTerceiro',
    'processoCompleto','anexoPresente','rogo','testemunhas','observacoes'
  ],
  Pendencias:['atendimentoId','descricao','responsavel','situacao'],
  Minutas:[
    'atendimentoId','fileId','url','numero','situacao','snapshot','templateId',
    'templateModified','revisor','revisadaEm'
  ],
  Historico:['entidade','registroId','antes','depois','operacao'],
  Configuracoes:['chave','valor'],
  Usuarios:['email','perfil','ativo'],
  Distribuicao:['atendimentoId','processoId','numero','juizo','data','responsavel','protocoloId'],
  Processos:['pessoaId','atendimentoId','numero','juizo','distribuidoEm','responsavel','movimentacoes'],
  Operacoes:['hash','resultado']
});

const COMMON=['id','versao','criadoEm','alteradoEm','usuario'];

const JURISDICOES = Object.freeze({
 'PELOTAS':['Amaral Ferrador','Arroio do Padre','Arroio Grande','Canguçu','Capão do Leão','Cerrito','Herval','Jaguarão','Morro Redondo','Pedro Osório','Pelotas','Piratini','São Lourenço do Sul','Turuçu'],
 'RIO GRANDE':['Chuí','Rio Grande','Santa Vitória do Palmar','São José do Norte'],
 'CAPÃO DA CANOA':['Arroio do Sal','Balneário Pinhal','Capão da Canoa','Caraá','Cidreira','Dom Pedro de Alcântara','Imbé','Itati','Mampituba','Maquiné','Morrinhos do Sul','Osório','Terra de Areia','Torres','Tramandaí','Três Cachoeiras','Três Forquilhas','Xangri-lá']
});
const DEFAULTS={
  rascunhos:'PENDENTE',
  vencimentoFuturo:'PENDENTE',
  anexoOrientacao:'',
  templateId:'',
  templateAprovado:false,
  entidades:[
    'COPAPEL — COLÔNIA DOS PESCADORES E AQUICULTORES PROFISSIONAIS ARTESANAIS DE PELOTAS',
    'COLÔNIA Z-1','COLÔNIA Z-2','COLÔNIA Z-3','COLÔNIA Z-11','Outro'
  ],
  municipios:Object.values(JURISDICOES).flat().sort((a,b)=>a.localeCompare(b,'pt-BR')),
  demandas:['Seguro-Defeso 2025'],
  categorias:['RG_CPF','RESIDENCIA','PROCESSO_ADMINISTRATIVO','PESCA','PROCURACAO','HIPOSSUFICIENCIA'],
  situacoes:['EM_PREPARACAO','ENCAMINHADO','CONFERIDO']
};

const ROLES={
  CONSULTA:['consulta'],
  CADASTRO:['consulta','cadastro'],
  CONFERENCIA:['consulta','cadastro','retificacao','conferencia'],
  JURIDICO:['consulta','cadastro','retificacao','conferencia','minuta'],
  ADMIN:['consulta','cadastro','retificacao','conferencia','minuta','administracao']
};

function props_(){
  return PropertiesService.getScriptProperties();
}

function fail_(message){
  throw new Error(message);
}

function required_(v,label){
  if(v===undefined||v===null||String(v).trim()==='')fail_('Informe '+label+'.');
  return v;
}

function uid_(){
  return Utilities.getUuid();
}

function hash_(value){
  return Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    typeof value==='string'?value:JSON.stringify(value)
  ).map(x=>('0'+((x+256)%256).toString(16)).slice(-2)).join('');
}

function id_(prefix,key){
  return prefix+'_'+hash_(key).slice(0,28);
}

function now_(){
  return new Date().toISOString();
}

function bool_(v){
  return v===true||v==='true';
}

function clone_(v){
  return JSON.parse(JSON.stringify(v));
}

function cfg_(){
  const c=clone_(DEFAULTS);
  all_('Configuracoes').forEach(r=>{
    c[r.chave]=JSON.parse(r.valor);
  });
  c.municipios=municipiosComJurisdicao_(c.municipios);
  return c;
}

/** Regra única para cadastro, planilha e minuta. */
function normalizarMunicipio_(texto){
  return String(texto||'').trim().toUpperCase().normalize('NFD')
    .replace(/[\u0300-\u036f]/g,'').replace(/[–—]/g,'-')
    .replace(/\s*-\s*/g,'-').replace(/\s+/g,' ');
}

function determinarJurisdicao(municipio){
  const nome=normalizarMunicipio_(municipio);
  for(const jurisdicao of Object.keys(JURISDICOES)){
    if(JURISDICOES[jurisdicao].some(m=>normalizarMunicipio_(m)===nome)){
      return jurisdicao;
    }
  }
  return '';
}

function municipiosComJurisdicao_(existentes){
  const porNome={};
  (Array.isArray(existentes)?existentes:[]).forEach(m=>{
    if(typeof m==='string'&&m.trim())porNome[normalizarMunicipio_(m)]=m.trim();
  });
  // Os nomes padronizados prevalecem; municípios adicionais são preservados.
  DEFAULTS.municipios.forEach(m=>porNome[normalizarMunicipio_(m)]=m);
  return Object.values(porNome).sort((a,b)=>a.localeCompare(b,'pt-BR'));
}

function jurisdicaoPessoa_(p){
  if(p.uf&&String(p.uf).trim().toUpperCase()!=='RS')return '';
  return determinarJurisdicao(p.cidade);
}

/** Atualização idempotente de instalações existentes, com auditoria de registros. */
function atualizarJurisdicoes_(){
  ensureEntitySchema_('Pessoas');
  const ctx={email:identity_(),op:'jurisdicoes_'+uid_(),hash:'jurisdicoes-v1',changes:[]};
  const config=all_('Configuracoes').find(r=>r.chave==='municipios');
  if(config){
    const lista=municipiosComJurisdicao_(JSON.parse(config.valor));
    if(JSON.stringify(lista)!==config.valor){
      change_(ctx,'Configuracoes',config.id,{chave:'municipios',valor:JSON.stringify(lista)},config.versao);
    }
  }
  const alterados=new Set();
  all_('Pessoas').forEach(p=>{
    const jurisdicao=jurisdicaoPessoa_(p);
    if(p.jurisdicao!==jurisdicao){
      change_(ctx,'Pessoas',p.id,Object.assign({},p,{jurisdicao}),p.versao);
      alterados.add(p.id);
    }
  });
  if(alterados.size){
    all_('Atendimentos').filter(a=>alterados.has(a.pessoaId)).forEach(a=>touch_(ctx,a));
  }
  if(ctx.changes.length)commit_(ctx,{mensagem:'Municípios e jurisdições atualizados.'});
}

let DATA_CACHE = {};

function resetData_(){
  DATA_CACHE={};
}

function ss_(){
  const id=props_().getProperty('SPREADSHEET_ID');
  if(!id)fail_('Execute instalar pelo editor do Apps Script.');
  return SpreadsheetApp.openById(id);
}

function headers_(entity){
  if(!SCHEMA[entity])fail_('Entidade inválida.');
  return COMMON.concat(SCHEMA[entity]);
}

/**
 * Mantém compatibilidade com bancos já instalados.
 * Só é permitida migração aditiva no final do cabeçalho.
 * Nenhuma coluna existente é apagada, movida ou renomeada.
 */
function ensureEntitySchema_(entity){
  if(!SCHEMA[entity])fail_('Entidade inválida.');

  const sh=ss_().getSheetByName(entity);
  if(!sh)fail_('Aba não encontrada: '+entity+'.');

  const expected=headers_(entity);
  const lastColumn=sh.getLastColumn();

  if(lastColumn===0){
    sh.getRange(1,1,1,expected.length).setValues([expected]);
    sh.setFrozenRows(1);
    sh.getRange(1,1,1,expected.length).setBackground('#12364a').setFontColor('#ffffff');
    sh.getRange(1,1,sh.getMaxRows(),expected.length).setNumberFormat('@');
    return sh;
  }

  const current=sh.getRange(1,1,1,lastColumn).getDisplayValues()[0];

  if(JSON.stringify(current)===JSON.stringify(expected)){
    return sh;
  }

  const prefixIsCompatible=
    current.length<expected.length&&
    current.every((value,index)=>value===expected[index]);

  if(!prefixIsCompatible){
    fail_('Cabeçalhos alterados: '+entity+'. A migração automática só acrescenta novas colunas ao final.');
  }

  const missing=expected.slice(current.length);
  sh.getRange(1,current.length+1,1,missing.length).setValues([missing]);
  sh.getRange(1,current.length+1,sh.getMaxRows(),missing.length).setNumberFormat('@');
  SpreadsheetApp.flush();
  resetData_();
  return sh;
}

function all_(entity){
  if(DATA_CACHE[entity])return DATA_CACHE[entity];

  const sh=ensureEntitySchema_(entity);
  const rows=sh.getDataRange().getDisplayValues();
  const heads=headers_(entity);

  if(JSON.stringify(rows[0])!==JSON.stringify(heads))fail_('Cabeçalhos alterados: '+entity);

  return DATA_CACHE[entity]=rows
    .slice(1)
    .filter(r=>r[0])
    .map(r=>Object.fromEntries(heads.map((h,i)=>[h,h==='versao'?Number(r[i]):r[i]])));
}

function get_(entity,id){
  return all_(entity).find(r=>r.id===id)||fail_('Registro não encontrado: '+entity);
}

function row_(entity,id){
  const sh=ensureEntitySchema_(entity);
  const values=sh.getRange(1,1,Math.max(sh.getLastRow(),1),1).getDisplayValues();
  const i=values.findIndex(r=>r[0]===id);
  return i<0?null:i;
}

function record_(entity,id,data,before,user){
  const r={
    id,
    versao:before?before.versao+1:1,
    criadoEm:before?before.criadoEm:now_(),
    alteradoEm:now_(),
    usuario:user
  };

  SCHEMA[entity].forEach(k=>r[k]=data[k]===undefined?'':data[k]);
  return r;
}

function change_(ctx,entity,id,data,version){
  const before=all_(entity).find(r=>r.id===id);

  if(before&&Number(version)!==before.versao){
    fail_('CONFLITO: o registro mudou. Reabra a ficha antes de salvar.');
  }

  const after=record_(entity,id,data,before,ctx.email);
  ctx.changes.push({entity,before:before||null,after});
  return after;
}

/** Atualização de dados, auditoria e recibo idempotente em uma única transação Sheets. */
function commit_(ctx,result){
  const changes=ctx.changes.slice();

  ctx.changes.forEach(c=>changes.push({
    entity:'Historico',
    after:record_(
      'Historico',
      uid_(),
      {
        entidade:c.entity,
        registroId:c.after.id,
        antes:JSON.stringify(c.before),
        depois:JSON.stringify(c.after),
        operacao:ctx.op
      },
      null,
      ctx.email
    )
  }));

  changes.push({
    entity:'Operacoes',
    after:record_(
      'Operacoes',
      ctx.op,
      {hash:ctx.hash,resultado:JSON.stringify(result)},
      null,
      ctx.email
    )
  });

  const next={};
  const requests=[];

  changes.forEach(c=>{
    const sh=ensureEntitySchema_(c.entity);
    let index=row_(c.entity,c.after.id);

    if(index===null){
      if(next[c.entity]===undefined)next[c.entity]=sh.getLastRow();
      index=next[c.entity]++;
    }

    if(index>=sh.getMaxRows()){
      requests.push({
        appendDimension:{
          sheetId:sh.getSheetId(),
          dimension:'ROWS',
          length:index-sh.getMaxRows()+1
        }
      });
    }

    const values=headers_(c.entity).map(k=>({
      userEnteredValue:{stringValue:String(c.after[k]===undefined?'':c.after[k])}
    }));

    requests.push({
      updateCells:{
        range:{
          sheetId:sh.getSheetId(),
          startRowIndex:index,
          endRowIndex:index+1,
          startColumnIndex:0,
          endColumnIndex:values.length
        },
        rows:[{values}],
        fields:'userEnteredValue'
      }
    });
  });

  Sheets.Spreadsheets.batchUpdate({requests},ss_().getId());
  SpreadsheetApp.flush();
  resetData_();
  return result;
}

function version_(row,expected){
  if(row.versao!==Number(expected))fail_('CONFLITO: registro alterado por outro usuário. Reabra a ficha.');
}

function touch_(ctx,a){
  return change_(
    ctx,
    'Atendimentos',
    a.id,
    Object.assign({},a,{
      revisao:Number(a.revisao||0)+1,
      conferencia:'',
      situacao:'EM_PREPARACAO'
    }),
    a.versao
  );
}

function snapshot_(a,p){
  return hash_({
    atendimento:a,
    pessoa:p,
    documentos:effectiveDocs_(a),
    pendencias:all_('Pendencias').filter(d=>d.atendimentoId===a.id)
  });
}

function identity_(){const email=Session.getActiveUser().getEmail().toLowerCase().trim();
if(!email)fail_('Identidade Google indisponível. Acesso bloqueado; revise a implantação.');
return email;
}
function authorize_(permission){const email=identity_();
const u=all_('Usuarios').find(r=>r.email===email&&bool_(r.ativo));
if(!u||!(ROLES[u.perfil]||[]).includes(permission))fail_('Acesso não autorizado para '+permission+'.');
return email;
}
function lock_(fn){const lock=LockService.getScriptLock();
if(!lock.tryLock(30000))fail_('Sistema ocupado. Tente novamente com a mesma operação.');
try{return fn();
}finally{lock.releaseLock();
}}

/** Executar somente no editor, nunca pelo navegador. Configure OWNER_EMAIL nas propriedades primeiro. */
function instalar(){
  return lock_(function(){
    resetData_();

    const email=identity_();
    if(email!==props_().getProperty('OWNER_EMAIL')){
      fail_('Configure OWNER_EMAIL com o e-mail da conta responsável, nas propriedades do script.');
    }

    const parent=DriveApp.getFolderById(PDA.parent);
    let rootId=props_().getProperty('ROOT_FOLDER_ID');

    if(!rootId){
      const name=PDA.name+' — '+ScriptApp.getScriptId();
      const iter=parent.getFoldersByName(name);
      const folder=iter.hasNext()?iter.next():parent.createFolder(name);
      if(iter.hasNext())fail_('Pastas de instalação duplicadas; selecione ROOT_FOLDER_ID manualmente.');
      rootId=folder.getId();
      props_().setProperty('ROOT_FOLDER_ID',rootId);
    }

    const root=DriveApp.getFolderById(rootId);
    let sid=props_().getProperty('SPREADSHEET_ID');

    if(!sid){
      const name='PDA Banco — '+ScriptApp.getScriptId();
      const matches=DriveApp.getFilesByName(name);
      const found=[];

      while(matches.hasNext()){
        const f=matches.next();
        if(f.getMimeType()===MimeType.GOOGLE_SHEETS&&!f.isTrashed())found.push(f);
      }

      if(found.length>1)fail_('Mais de um banco encontrado; defina SPREADSHEET_ID.');
      sid=found.length?found[0].getId():SpreadsheetApp.create(name).getId();
      props_().setProperty('SPREADSHEET_ID',sid);
    }

    DriveApp.getFileById(sid).moveTo(root);

    const ss=SpreadsheetApp.openById(sid);
    ss.setSpreadsheetTimeZone(PDA.tz);

    Object.keys(SCHEMA).forEach(entity=>{
      const heads=headers_(entity);
      const sh=ss.getSheetByName(entity)||ss.insertSheet(entity);

      if(sh.getLastRow()===0){
        sh.getRange(1,1,1,heads.length).setValues([heads]);
        sh.setFrozenRows(1);
        sh.getRange(1,1,1,heads.length).setBackground('#12364a').setFontColor('#ffffff');
        sh.getRange(1,1,sh.getMaxRows(),heads.length).setNumberFormat('@');
      }else{
        ensureEntitySchema_(entity);
      }
    });

    SpreadsheetApp.flush();
    resetData_();

    const ctx={
      email,
      op:'install_'+uid_(),
      hash:'installation',
      changes:[]
    };

    Object.keys(DEFAULTS).forEach(chave=>{
      if(!all_('Configuracoes').some(r=>r.chave===chave)){
        change_(
          ctx,
          'Configuracoes',
          id_('CFG',chave),
          {chave,valor:JSON.stringify(DEFAULTS[chave])}
        );
      }
    });

    if(!all_('Usuarios').some(r=>r.email===email)){
      change_(
        ctx,
        'Usuarios',
        id_('USR',email),
        {email,perfil:'ADMIN',ativo:true}
      );
    }

    return commit_(ctx,{
      planilha:ss.getUrl(),
      pasta:root.getUrl(),
      mensagem:'Instalação estrutural concluída; homologação Google ainda necessária.'
    });
  });
}

function cpf_(input){
  const s=String(input||'').replace(/\D/g,'');

  if(!/^\d{11}$/.test(s)||/^(\d)\1+$/.test(s))fail_('CPF inválido.');

  for(let j=9;j<11;j++){
    let n=0;
    for(let i=0;i<j;i++)n+=Number(s[i])*(j+1-i);
    let d=(n*10)%11;
    if(d===10)d=0;
    if(d!==Number(s[j]))fail_('CPF inválido.');
  }

  return s;
}

function date_(s){
  if(!/^\d{2}\/\d{2}\/\d{4}$/.test(s||''))fail_('Data deve usar DD/MM/AAAA.');

  const [d,m,y]=s.split('/').map(Number);
  const date=new Date(Date.UTC(y,m-1,d));

  if(date.getUTCFullYear()!==y||date.getUTCMonth()!==m-1||date.getUTCDate()!==d){
    fail_('Data inválida.');
  }

  return date;
}

function today_(){
  return date_(Utilities.formatDate(new Date(),PDA.tz,'dd/MM/yyyy'));
}

function parcelasDefeso_(value){
  const n=Number(value);

  if(
    !Number.isInteger(n)||
    n<SEGURO_DEFESO_2025.minParcelas||
    n>SEGURO_DEFESO_2025.maxParcelas
  ){
    fail_('Informe quantas parcelas do seguro-defeso não foram recebidas: de 1 a 4.');
  }

  return n;
}

function moneyBR_(value){
  return Number(value||0).toLocaleString('pt-BR',{
    minimumFractionDigits:2,
    maximumFractionDigits:2
  });
}

function valorCausaDefeso_(parcelas){
  return parcelasDefeso_(parcelas)*SEGURO_DEFESO_2025.salarioMinimo;
}

function validatePerson_(input,c,complete){
  const p={};
  SCHEMA.Pessoas.forEach(k=>p[k]=typeof input[k]==='string'?input[k].trim():input[k]);

  p.cpf=cpf_(p.cpf);
  required_(p.nome,'nome completo');

  if(p.nome.length>200)fail_('Nome muito longo.');

  if(complete){
    [
      'nascimento','telefone','tipoVia','via','numero','bairro','cidade','uf',
      'entidade','analfabeto','parcelasNaoRecebidas'
    ].forEach(k=>required_(p[k],k));
  }

  if(p.parcelasNaoRecebidas!==''){
    p.parcelasNaoRecebidas=String(parcelasDefeso_(p.parcelasNaoRecebidas));
  }

  if(p.nascimento&&date_(p.nascimento)>today_())fail_('Nascimento não pode estar no futuro.');

  if(p.telefone&&!/^\d{10,11}$/.test(p.telefone.replace(/\D/g,''))){
    fail_('Telefone deve conter DDD e 10 ou 11 dígitos.');
  }

  if(p.uf&&!/^(AC|AL|AP|AM|BA|CE|DF|ES|GO|MA|MT|MS|MG|PA|PB|PR|PE|PI|RJ|RN|RS|RO|RR|SC|SP|SE|TO)$/.test(p.uf)){
    fail_('UF inválida.');
  }

  if(p.cidade&&!c.municipios.includes(p.cidade))fail_('Município não cadastrado.');
  // A jurisdição é derivada do município, nunca do valor enviado pelo navegador.
  p.jurisdicao=jurisdicaoPessoa_(p);
  if(p.entidade&&!c.entidades.includes(p.entidade))fail_('Entidade não cadastrada.');
  if(p.entidade==='Outro')required_(p.outraEntidade,'outra entidade');

  if(p.analfabeto&&!['SIM','NAO'].includes(p.analfabeto)){
    fail_('Informe a condição registrada no documento de identidade.');
  }

  return p;
}

function validateAtend_(input,c){
  const a={};

  [
    'pessoaId','demanda','referencia','parcelas','outrosCasos','observacoes',
    'responsavel','enderecamento','secaoJudiciaria','valorCausa','localData'
  ].forEach(k=>a[k]=String(input[k]||'').trim());

  ['pessoaId','demanda','referencia','parcelas'].forEach(k=>required_(a[k],k));

  if(!c.demandas.includes(a.demanda))fail_('Demanda não cadastrada.');

  if(!['Todas de 2025','Somente a última de 2025','Outros casos'].includes(a.parcelas)){
    fail_('Opção de parcelas inválida.');
  }

  if(a.parcelas==='Outros casos')required_(a.outrosCasos,'descrição dos outros casos');

  if(a.responsavel&&!all_('Usuarios').some(u=>u.email===a.responsavel&&bool_(u.ativo))){
    fail_('Responsável não autorizado.');
  }

  /* O valor da causa nunca é aceito do navegador. É recalculado a partir do cadastro da pessoa. */
  const p=get_('Pessoas',a.pessoaId);
  a.valorCausa=moneyBR_(valorCausaDefeso_(p.parcelasNaoRecebidas));

  return a;
}

function address_(p){
  const via=[p.tipoVia,p.via].filter(Boolean).join(' ');
  return [via,p.numero,p.complemento,p.bairro].filter(Boolean).join(', ');
}

function eligibility_(a,manual){
  const errors=[];
  const p=get_('Pessoas',a.pessoaId);
  const c=cfg_();

  try{
    validatePerson_(p,c,true);
    validateAtend_(a,c);
  }catch(e){
    errors.push(e.message);
  }

  if(c.vencimentoFuturo==='PENDENTE')errors.push('Definir política de vencimento futuro.');
  if(!c.anexoOrientacao)errors.push('Identificar o anexo exigido.');

  const docs=effectiveDocs_(a);

  c.categorias.forEach(cat=>{
    const ds=docs.filter(d=>d.categoria===cat);

    if(!ds.length)errors.push('Anexar '+documentLabel_(cat)+'.');

    ds.forEach(d=>{
      if(manual&&!bool_(d.conferido))errors.push('Conferir '+d.nome+'.');

      if(cat==='RESIDENCIA'){
        try{
          const days=(today_()-date_(d.vencimento))/86400000;
          if(days>60)errors.push('Comprovante vencido há mais de 60 dias.');
          if(days<0&&c.vencimentoFuturo!=='ACEITAR')errors.push('Vencimento futuro não autorizado.');
        }catch(e){
          errors.push('Residência: '+e.message);
        }

        if(manual&&bool_(d.terceiro)&&!bool_(d.declaracaoTerceiro)){
          errors.push('Conferir declaração de residência na própria fatura.');
        }
      }

      if(
        manual&&
        cat==='PROCESSO_ADMINISTRATIVO'&&
        (!bool_(d.processoCompleto)||!bool_(d.anexoPresente))
      ){
        errors.push('Conferir processo administrativo completo e anexo.');
      }

      if(
        manual&&
        cat==='PROCURACAO'&&
        p.analfabeto==='SIM'&&
        (!bool_(d.rogo)||!bool_(d.testemunhas))
      ){
        errors.push('Conferir assinatura a rogo e duas testemunhas.');
      }
    });
  });

  if(all_('Pendencias').some(x=>x.atendimentoId===a.id&&x.situacao!=='RESOLVIDA')){
    errors.push('Existem pendências abertas.');
  }

  return [...new Set(errors)];
}

const PERSON_DOC_OWNER_PREFIX='PESSOA:';

const DOCUMENT_LABELS={
  RG_CPF:'Documento de identidade e CPF',
  RESIDENCIA:'Comprovante de residência',
  PROCESSO_ADMINISTRATIVO:'Processo administrativo',
  PESCA:'Documentos de pesca',
  PROCURACAO:'Procuração',
  HIPOSSUFICIENCIA:'Declaração de hipossuficiência'
};

const LEGACY_DOCUMENT_FOLDERS={
  '01 - Documento de identidade e CPF':'RG_CPF',
  '02 - Comprovante de residência':'RESIDENCIA',
  '03 - Processo administrativo':'PROCESSO_ADMINISTRATIVO',
  '04 - Documentos de pesca':'PESCA',
  '05 - Procuração':'PROCURACAO',
  '06 - Declaração de hipossuficiência':'HIPOSSUFICIENCIA'
};

function safeName_(value){
  return String(value||'')
    .trim()
    .replace(/[\\/:*?"<>|]/g,'-')
    .replace(/[\r\n\t]/g,' ')
    .replace(/\s+/g,' ')
    .slice(0,180);
}

function cpfDisplay_(cpf){
  const value=String(cpf||'').replace(/\D/g,'');

  if(value.length!==11)return String(cpf||'').trim();

  return value.replace(
    /(\d{3})(\d{3})(\d{3})(\d{2})/,
    '$1.$2.$3-$4'
  );
}

function personOwnerKey_(pessoaId){
  return PERSON_DOC_OWNER_PREFIX+pessoaId;
}

function personIdFromOwner_(owner){
  const value=String(owner||'');

  return value.startsWith(PERSON_DOC_OWNER_PREFIX)
    ?value.slice(PERSON_DOC_OWNER_PREFIX.length)
    :'';
}

function documentLabel_(categoria){
  return DOCUMENT_LABELS[categoria]||categoria;
}

function uniqueFileName_(folder,base,ext){
  let name=base+'.'+ext;

  if(!folder.getFilesByName(name).hasNext()){
    return name;
  }

  let n=2;

  while(
    folder
      .getFilesByName(base+' ('+n+').'+ext)
      .hasNext()
  ){
    n++;
  }

  return base+' ('+n+').'+ext;
}

function extensionFromFile_(file){
  const mime=file.getMimeType();

  if(mime==='application/pdf')return 'pdf';
  if(mime==='image/jpeg')return 'jpg';
  if(mime==='image/png')return 'png';

  const match=String(file.getName()||'').match(/\.([A-Za-z0-9]+)$/);
  return match?match[1].toLowerCase():'bin';
}

function flattenLegacyPersonFolders_(folder,p){
  const iterator=folder.getFolders();
  const legacy=[];

  while(iterator.hasNext()){
    const child=iterator.next();
    const categoria=LEGACY_DOCUMENT_FOLDERS[child.getName()];

    if(categoria){
      legacy.push({
        child,
        categoria
      });
    }
  }

  legacy.forEach(item=>{
    const files=item.child.getFiles();

    while(files.hasNext()){
      const file=files.next();
      const ext=extensionFromFile_(file);

      const base=
        documentLabel_(item.categoria)+
        '.'+
        safeName_(p.nome);

      const name=
        uniqueFileName_(
          folder,
          base,
          ext
        );

      file.setName(name);
      file.moveTo(folder);
    }

    item.child.setTrashed(true);
  });
}

function personFolder_(p){
  required_(p&&p.id,'id da pessoa');

  const root=DriveApp.getFolderById(PDA.parent);
  const desiredName=
    safeName_(p.nome)+
    ' - '+
    cpfDisplay_(p.cpf);

  const iterator=root.getFolders();
  const exact=[];
  const legacy=[];
  const rawCpf=String(p.cpf||'');
  const formattedCpf=cpfDisplay_(p.cpf);

  while(iterator.hasNext()){
    const folder=iterator.next();
    const name=folder.getName();

    if(name===desiredName){
      exact.push(folder);
      continue;
    }

    if(
      name.includes(p.id)||
      (rawCpf&&name.includes(rawCpf))||
      (formattedCpf&&name.includes(formattedCpf))
    ){
      legacy.push(folder);
    }
  }

  if(exact.length>1){
    fail_(
      'Há mais de uma pasta com o nome esperado para '+
      p.nome+
      '. Administração deve reconciliar as pastas.'
    );
  }

  if(exact.length===1&&legacy.length){
    fail_(
      'Há uma pasta atual e outra pasta antiga para '+
      p.nome+
      '. Administração deve reconciliar as pastas.'
    );
  }

  if(legacy.length>1){
    fail_(
      'Há mais de uma pasta antiga relacionada a '+
      p.nome+
      '. Administração deve reconciliar as pastas.'
    );
  }

  const folder=
    exact.length
      ?exact[0]
      :legacy.length
        ?legacy[0]
        :root.createFolder(desiredName);

  if(folder.getName()!==desiredName){
    folder.setName(desiredName);
  }

  flattenLegacyPersonFolders_(folder,p);

  return folder;
}

function atendimentoRoot_(p){
  const pessoaFolder=personFolder_(p);
  const iterator=pessoaFolder.getFoldersByName('Atendimentos');

  const folder=
    iterator.hasNext()
      ?iterator.next()
      :pessoaFolder.createFolder('Atendimentos');

  if(iterator.hasNext()){
    fail_(
      'Há mais de uma pasta "Atendimentos" para '+
      p.nome+
      '.'
    );
  }

  return folder;
}

function atendimentoFolderName_(a){
  return safeName_(
    a.demanda+
    ' - '+
    a.referencia
  ).slice(0,230);
}

function folder_(a){
  const p=get_('Pessoas',a.pessoaId);
  const desiredName=atendimentoFolderName_(a);

  if(a.folderId){
    try{
      const existing=DriveApp.getFolderById(a.folderId);

      if(existing.getName()!==desiredName){
        existing.setName(desiredName);
      }

      return existing;

    }catch(e){}
  }

  const root=atendimentoRoot_(p);
  const iterator=root.getFoldersByName(desiredName);

  const folder=
    iterator.hasNext()
      ?iterator.next()
      :root.createFolder(desiredName);

  if(iterator.hasNext()){
    fail_(
      'Há pastas duplicadas para este atendimento; administração deve reconciliar.'
    );
  }

  return folder;
}

function filePayload_(q){
  const mime=String(q.mime||'').trim();

  if(
    ![
      'application/pdf',
      'image/jpeg',
      'image/png'
    ].includes(mime)
  ){
    fail_('Use PDF, JPEG ou PNG.');
  }

  if(
    typeof q.base64!=='string'||
    q.base64.length>PDA.maxBytes*1.4
  ){
    fail_('Limite de 5 MB por arquivo.');
  }

  const bytes=Utilities.base64Decode(q.base64);

  if(
    !bytes.length||
    bytes.length>PDA.maxBytes
  ){
    fail_('Arquivo vazio ou maior que 5 MB.');
  }

  const sig=
    bytes
      .slice(0,8)
      .map(x=>(x+256)%256);

  if(
    mime==='application/pdf'&&
    String.fromCharCode(...sig.slice(0,5))!=='%PDF-'
  ){
    fail_('Conteúdo não corresponde a um PDF.');
  }

  if(
    mime==='image/jpeg'&&
    (
      sig[0]!==255||
      sig[1]!==216
    )
  ){
    fail_('Conteúdo não corresponde a uma imagem JPEG.');
  }

  if(
    mime==='image/png'&&
    sig.join(',')!=='137,80,78,71,13,10,26,10'
  ){
    fail_('Conteúdo não corresponde a uma imagem PNG.');
  }

  const digest=
    Utilities.computeDigest(
      Utilities.DigestAlgorithm.SHA_256,
      bytes
    )
      .map(
        x=>(
          '0'+
          ((x+256)%256).toString(16)
        ).slice(-2)
      )
      .join('');

  const ext={
    'application/pdf':'pdf',
    'image/jpeg':'jpg',
    'image/png':'png'
  }[mime];

  return {
    bytes,
    digest,
    ext,
    mime
  };
}

function driveFileDigest_(file){
  return Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    file.getBlob().getBytes()
  )
    .map(
      x=>(
        '0'+
        ((x+256)%256).toString(16)
      ).slice(-2)
    )
    .join('');
}

function plannedDocumentName_(folder,categoria,p,payload,committedCount){
  const base=
    documentLabel_(categoria)+
    '.'+
    safeName_(p.nome);

  const preferred=
    committedCount>0
      ?base+' ('+(committedCount+1)+').'+payload.ext
      :base+'.'+payload.ext;

  const iterator=
    folder.getFilesByName(preferred);

  if(!iterator.hasNext()){
    return preferred;
  }

  const existing=iterator.next();

  if(
    !iterator.hasNext()&&
    driveFileDigest_(existing)===payload.digest
  ){
    return preferred;
  }

  return uniqueFileName_(
    folder,
    base,
    payload.ext
  );
}

function createOrReuseDocumentFile_(folder,name,payload){
  const iterator=
    folder.getFilesByName(name);

  if(iterator.hasNext()){
    const existing=iterator.next();

    if(
      !iterator.hasNext()&&
      driveFileDigest_(existing)===payload.digest
    ){
      return existing;
    }
  }

  return folder.createFile(
    Utilities.newBlob(
      payload.bytes,
      payload.mime,
      name
    )
  );
}

function personUpload_(ctx,q){
  const p=get_('Pessoas',q.pessoaId);
  const c=cfg_();

  if(!c.categorias.includes(q.categoria)){
    fail_('Categoria inválida.');
  }

  const payload=filePayload_(q);
  const owner=personOwnerKey_(p.id);

  const prior=
    all_('Documentos')
      .find(d=>
        d.atendimentoId===owner&&
        d.categoria===q.categoria&&
        d.hash===payload.digest&&
        bool_(d.vigente)
      );

  if(prior){
    return {
      documento:prior,
      pessoa:p,
      mensagem:
        'Arquivo já anexado; preservado sem duplicação.'
    };
  }

  if(q.categoria==='RESIDENCIA'){
    date_(q.vencimento);
  }

  const folder=personFolder_(p);
  const did=id_('DOC',ctx.op);

  const committedCount=
    all_('Documentos')
      .filter(d=>
        d.atendimentoId===owner&&
        d.categoria===q.categoria&&
        bool_(d.vigente)
      )
      .length;

  const name=
    plannedDocumentName_(
      folder,
      q.categoria,
      p,
      payload,
      committedCount
    );

  const file=
    createOrReuseDocumentFile_(
      folder,
      name,
      payload
    );

  ctx.effects.push(
    'Documento da pessoa preservado no Drive: '+
    file.getUrl()
  );

  const documento=
    change_(
      ctx,
      'Documentos',
      did,
      {
        atendimentoId:owner,
        categoria:q.categoria,
        fileId:file.getId(),
        url:file.getUrl(),
        nome:name,
        hash:payload.digest,
        mime:payload.mime,
        substituiId:'',
        vigente:true,
        vencimento:q.vencimento||'',
        terceiro:bool_(q.terceiro),
        conferido:false,
        declaracaoTerceiro:false,
        processoCompleto:false,
        anexoPresente:false,
        rogo:false,
        testemunhas:false,
        observacoes:''
      }
    );

  return {
    documento,
    pessoa:p,
    folderId:folder.getId(),
    folderUrl:folder.getUrl(),
    mensagem:
      'Documento salvo na pasta da pessoa.'
  };
}

function effectiveDocs_(a){
  const owner=
    personOwnerKey_(
      a.pessoaId
    );

  const docs=
    all_('Documentos')
      .filter(d=>
        bool_(d.vigente)&&
        (
          d.atendimentoId===a.id||
          d.atendimentoId===owner
        )
      );

  const result=[];

  cfg_().categorias
    .forEach(category=>{
      const specific=
        docs.filter(d=>
          d.categoria===category&&
          d.atendimentoId===a.id
        );

      const shared=
        docs.filter(d=>
          d.categoria===category&&
          d.atendimentoId===owner
        );

      result.push(
        ...(
          specific.length
            ?specific
            :shared
        )
      );
    });

  return result;
}

function upload_(ctx,q){
  const a=get_('Atendimentos',q.atendimentoId);
  version_(a,q.versao);

  const c=cfg_();

  if(!c.categorias.includes(q.categoria)){
    fail_('Categoria inválida.');
  }

  const payload=filePayload_(q);

  const prior=
    all_('Documentos')
      .find(d=>
        d.atendimentoId===a.id&&
        d.categoria===q.categoria&&
        d.hash===payload.digest&&
        bool_(d.vigente)
      );

  if(prior){
    return {
      documento:prior,
      atendimento:a,
      mensagem:
        'Arquivo já anexado; preservado sem duplicação.'
    };
  }

  if(q.categoria==='RESIDENCIA'){
    date_(q.vencimento);
  }

  let previous=null;

  if(q.substituiId){
    previous=
      get_(
        'Documentos',
        q.substituiId
      );

    if(
      previous.atendimentoId!==a.id||
      previous.categoria!==q.categoria||
      !bool_(previous.vigente)
    ){
      fail_('Substituição inválida.');
    }
  }

  const p=get_('Pessoas',a.pessoaId);
  const folder=folder_(a);
  const did=id_('DOC',ctx.op);

  const committedCount=
    all_('Documentos')
      .filter(d=>
        d.atendimentoId===a.id&&
        d.categoria===q.categoria&&
        bool_(d.vigente)&&
        (
          !previous||
          d.id!==previous.id
        )
      )
      .length;

  const name=
    plannedDocumentName_(
      folder,
      q.categoria,
      p,
      payload,
      committedCount
    );

  const file=
    createOrReuseDocumentFile_(
      folder,
      name,
      payload
    );

  ctx.effects.push(
    'Arquivo preservado no Drive: '+
    file.getUrl()
  );

  if(previous){
    change_(
      ctx,
      'Documentos',
      previous.id,
      Object.assign(
        {},
        previous,
        {
          vigente:false
        }
      ),
      previous.versao
    );
  }

  const d=
    change_(
      ctx,
      'Documentos',
      did,
      {
        atendimentoId:a.id,
        categoria:q.categoria,
        fileId:file.getId(),
        url:file.getUrl(),
        nome:name,
        hash:payload.digest,
        mime:payload.mime,
        substituiId:q.substituiId||'',
        vigente:true,
        vencimento:q.vencimento||'',
        terceiro:bool_(q.terceiro),
        conferido:false,
        declaracaoTerceiro:false,
        processoCompleto:false,
        anexoPresente:false,
        rogo:false,
        testemunhas:false,
        observacoes:''
      }
    );

  const changed=
    touch_(
      ctx,
      Object.assign(
        {},
        a,
        {
          folderId:
            folder.getId()
        }
      )
    );

  return {
    documento:d,
    atendimento:changed,
    mensagem:
      'Arquivo gravado. Conferência humana pendente.'
  };
}

const MODULES={
  PAINEL:'Painel',
  PESS:'Pessoas',
  ATEND:'Atendimentos',
  ACOMP:'Ficha e conferência',
  MIN:'Minutas',
  DIST:'Distribuição',
  PROC:'Processos',
  ADM:'Administração'
};

function doGet(){
